INSERT INTO `locales_source` VALUES (5985,_binary 'Reference fields have several widgets available on the <em>Manage form display</em> page:','','none');
INSERT INTO `locales_source` VALUES (5986,_binary 'The <em>Check boxes/radio buttons</em> widget displays the existing entities for the entity type as check boxes or radio buttons based on the <em>Allowed number of values</em> set for the field.','','none');
INSERT INTO `locales_source` VALUES (5987,_binary 'The <em>Select list</em> widget displays the existing entities in a drop-down list or scrolling list box based on the <em>Allowed number of values</em> setting for the field.','','none');
INSERT INTO `locales_source` VALUES (5988,_binary 'The <em>Autocomplete</em> widget displays text fields in which users can type entity labels based on the <em>Allowed number of values</em>. The widget can be configured to display all entities that contain the typed characters or restricted to those starting with those characters.','','none');
INSERT INTO `locales_source` VALUES (5989,_binary 'The <em>Autocomplete (Tags style)</em> widget displays a multi-text field in which users can type in a comma-separated list of entity labels.','','none');
INSERT INTO `locales_source` VALUES (5990,_binary 'Your server is not capable of displaying file upload progress. File upload progress requires an Apache server running PHP with mod_php or Nginx with PHP-FPM.','','none');
INSERT INTO `locales_source` VALUES (5991,_binary 'Your server is not capable of displaying file upload progress. File upload progress requires PHP be run with mod_php or PHP-FPM and not as FastCGI.','','none');
