INSERT INTO `locales_source` VALUES (6207,_binary 'The installer requires write permissions to %translations_directory during the installation process. The <a href=\":handbook_url\">webhosting issues</a> documentation section offers help on this and other topics.','','none');
INSERT INTO `locales_source` VALUES (6208,_binary 'The installer requires to contact the translation server to download a translation file. Check your internet connection and verify that your website can reach the translation server at <a href=\":server_url\">@server_url</a>.','','none');
INSERT INTO `locales_source` VALUES (6209,_binary 'The %language translation file is not available at the translation server. <a href=\":url\">Choose a different language</a> or select English and translate your website later.','','none');
INSERT INTO `locales_source` VALUES (6210,_binary 'The %language translation file could not be downloaded. <a href=\":url\">Choose a different language</a> or select English and translate your website later.','','none');
INSERT INTO `locales_source` VALUES (6211,_binary 'The @drupal installer requires that you create a %file as part of the installation process. Copy the %default_file file to %file. More details about installing Drupal are available in <a href=\":install_txt\">INSTALL.txt</a>.','','none');
INSERT INTO `locales_source` VALUES (6212,_binary '@drupal requires read permissions to %file at all times. The <a href=\":handbook_url\">webhosting issues</a> documentation section offers help on this and other topics.','','none');
