INSERT INTO `locales_source` VALUES (6229,_binary '<ul>\n<li>To start over, you must empty your existing database and copy <em>default.settings.php</em> over <em>settings.php</em>.</li>\n<li>To upgrade an existing installation, proceed to the <a href=\":update-url\">update script</a>.</li>\n<li>View your <a href=\":base-url\">existing site</a>.</li>\n</ul>','','none');
INSERT INTO `locales_source` VALUES (6230,_binary 'All necessary changes to %dir and %file have been made, so you should remove write permissions to them now in order to avoid security risks. If you are unsure how to do so, consult the <a href=\":handbook_url\">online handbook</a>.','','none');
