INSERT INTO `locales_source` VALUES (6481,_binary 'The Toolbar module provides a toolbar for site administrators, which displays tabs and trays provided by the Toolbar module itself and other modules. For more information, see the <a href=\":toolbar_docs\">online documentation for the Toolbar module</a>.','','none');
