INSERT INTO `locales_source` VALUES (6557,_binary 'The Automated Cron module runs cron operations for your site using normal browser/page requests instead of having to set up a separate cron job. The Automated Cron module checks at the end of each server response when cron operation was last ran and, if it has been too long since last run, it executes the cron tasks after sending a server response. For more information, see the <a href=\":automated_cron-documentation\">online documentation for the Automated Cron module</a>.','','none');
INSERT INTO `locales_source` VALUES (6558,_binary 'Configuring Automated Cron','','none');
INSERT INTO `locales_source` VALUES (6559,_binary 'On the <a href=\":cron-settings\">Cron page</a>, you can set the frequency (time interval) for running cron jobs.','','none');
INSERT INTO `locales_source` VALUES (6560,_binary 'Disabling Automated Cron','','none');
INSERT INTO `locales_source` VALUES (6561,_binary 'To disable automated cron, the recommended method is to uninstall the module, to reduce site overhead. If you only want to disable it temporarily, you can set the frequency to Never on the Cron page, and then change the frequency back when you want to start it up again.','','none');
