INSERT INTO `locales_source` VALUES (6597,_binary 'The minimum character length for a word to be added to the index. Searches must include a keyword of at least this length.','','none');
INSERT INTO `locales_source` VALUES (6598,_binary 'Checking site status','','none');
INSERT INTO `locales_source` VALUES (6599,_binary 'The <a href=\":status\">Status report</a> provides an overview of the configuration, status, and health of your site. Review this report to make sure there are not any problems to address, and to find information about the software your site and web server are using.','','none');
INSERT INTO `locales_source` VALUES (6600,_binary 'In order for the site and its modules to continue to operate well, a set of routine administrative operations must run on a regular basis; these operations are known as <em>cron</em> tasks. On the <a href=\":cron\">Cron page</a>, you can configure cron to run periodically as part of server responses by installing the <em>Automated Cron</em> module, or you can turn this off and trigger cron from an outside process on your web server. You can verify the status of cron tasks by visiting the <a href=\":status\">Status report page</a>. For more information, see the <a href=\":handbook\">online documentation for configuring cron jobs</a>.','','none');
