INSERT INTO `locales_source` VALUES (6764,_binary 'The Syslog module logs events by sending messages to the logging facility of your web server\'s operating system. Syslog is an operating system administrative logging tool that provides valuable information for use in system management and security auditing. Most suited to medium and large sites, Syslog provides filtering tools that allow messages to be routed by type and severity. For more information, see the <a href=\":syslog\">online documentation for the Syslog module</a>, as well as PHP\'s documentation pages for the <a href=\"http://php.net/manual/function.openlog.php\">openlog</a> and <a href=\"http://php.net/manual/function.syslog.php\">syslog</a> functions.','','none');
