INSERT INTO `locales_source` VALUES (7119,_binary 'The Inline Form Errors module makes it easier for users to identify which errors need to be resolved by providing a summary of all errors and by placing the individual error messages next to the form elements themselves. For more information, see the <a href=\":inline_form_error\">online documentation for the Inline Form Errors module</a>.','','none');
INSERT INTO `locales_source` VALUES (7120,_binary 'Displaying error messages','','none');
INSERT INTO `locales_source` VALUES (7121,_binary 'When a form is not filled in correctly (for example, if a required field is left blank), a warning message is displayed at the top of the form. This message links to the affected form elements, and individual error messages are displayed next to each form element.','','none');
INSERT INTO `locales_source` VALUES (7122,_binary 'Displaying error messages in browsers with HTML5 form validation','','none');
