INSERT INTO `locales_source` VALUES (7248,_binary 'The Media module manages the creation, editing, deletion, settings, and display of media. Items are typically images, documents, slideshows, YouTube videos, tweets, Instagram photos, etc. You can reference media items from any other content on your site. For more information, see the <a href=\":media\">online documentation for the Media module</a>.','','none');
INSERT INTO `locales_source` VALUES (7249,_binary 'Listing media items','','none');
INSERT INTO `locales_source` VALUES (7250,_binary 'Media items are listed at the <a href=\":media-collection\">media administration page</a>.','','none');
INSERT INTO `locales_source` VALUES (7251,_binary 'Adding media to other content','','none');
INSERT INTO `locales_source` VALUES (7252,_binary 'Users with permission to administer content types can add media support by adding a media reference field to the content type on the content type administration page. (The same is true of block types, taxonomy terms, user profiles, and other content that supports fields.) A media reference field can refer to any configured media type. It is possible to allow multiple media types in the same field.','','none');
INSERT INTO `locales_source` VALUES (7253,_binary 'Differences between Media, File, and Image reference fields','','none');
INSERT INTO `locales_source` VALUES (7254,_binary '<em>Media</em> reference fields offer several advantages over basic <em>File</em> and <em>Image</em> references:','','none');
INSERT INTO `locales_source` VALUES (7255,_binary 'Media reference fields can reference multiple media types in the same field.','','none');
INSERT INTO `locales_source` VALUES (7256,_binary 'Fields can also be added to media types themselves, which means that custom metadata like descriptions and taxonomy tags can be added for the referenced media. (Basic file and image fields do not support this.)','','none');
INSERT INTO `locales_source` VALUES (7257,_binary 'Media types for audio and video files are provided by default, so there is no need for additional configuration to upload these media.','','none');
