INSERT INTO `locales_source` VALUES (7280,_binary 'On the <a href=\":cache-settings\">Performance page</a>, you can configure how long browsers and proxies may cache pages based on the Cache-Control header; this setting is ignored by the Internal Page Cache module, which caches pages permanently until invalidation, unless they carry an Expires header. There is no other configuration.','','none');
INSERT INTO `locales_source` VALUES (7281,_binary 'The Settings Tray module allows users with the <a href=\":administer_block_permission\">Administer blocks</a> and <a href=\":contextual_permission\">Use contextual links</a> permissions to edit blocks without visiting a separate page. For more information, see the <a href=\":handbook_url\">online documentation for the Settings Tray module</a>.','','none');
INSERT INTO `locales_source` VALUES (7282,_binary 'Editing blocks in place','','none');
INSERT INTO `locales_source` VALUES (7283,_binary 'To edit blocks in place, either click the <strong>Edit</strong> button in the toolbar and then click on the block, or choose \"Quick edit\" from the block\'s contextual link. (See the <a href=\":contextual\">Contextual Links module help</a> for more information about how to use contextual links.)','','none');
