INSERT INTO `locales_source` VALUES (8206,_binary 'You will be left on the <em>Add user</em> page; repeat these steps if you have more user accounts to create.','','none');
INSERT INTO `locales_source` VALUES (8207,_binary 'Create a new role.','','none');
INSERT INTO `locales_source` VALUES (8208,_binary 'Click <em>Add role</em>.','','none');
INSERT INTO `locales_source` VALUES (8209,_binary 'Enter the desired <em>Role name</em>. If desired, click <em>Edit</em> to change the <em>Machine name</em> for the role.','','none');
INSERT INTO `locales_source` VALUES (8210,_binary 'Click <em>Save</em>. You should be returned to the <em>Roles</em> page and your new role should be in the role list.','','none');
INSERT INTO `locales_source` VALUES (8211,_binary 'What is a user?','','none');
INSERT INTO `locales_source` VALUES (8212,_binary 'A user is anyone accessing or viewing your site. <em>Anonymous</em> users are users who are not logged in, and <em>Authenticated</em> users are users who are logged in.','','none');
INSERT INTO `locales_source` VALUES (8213,_binary 'What is a role?','','none');
INSERT INTO `locales_source` VALUES (8214,_binary '<em>Roles</em> are used to group and classify users; each user can be assigned one or more roles. There are also special roles for all anonymous and all authenticated users.','','none');
INSERT INTO `locales_source` VALUES (8215,_binary 'What is a permission?','','none');
INSERT INTO `locales_source` VALUES (8216,_binary 'Overview of managing user accounts and visitors','','none');
INSERT INTO `locales_source` VALUES (8217,_binary 'Modify the permissions for an existing role.','','none');
INSERT INTO `locales_source` VALUES (8218,_binary 'Review the permissions for the role, paying particular attention to the permissions marked with <em>Warning: Give to trusted roles only; this permission has security implications.</em> Uncheck permissions that this role should not have, in the row of the permission and the column of the role; check permissions that this role should have.','','none');
