INSERT INTO `locales_source` VALUES (8258,_binary 'Check <em>Make this the default form</em> and click <em>Save</em>.','','none');
INSERT INTO `locales_source` VALUES (8259,_binary 'Click <em>Save settings</em>. You should be returned to the <em>Manage fields</em> page, with your new field in the list.','','none');
