INSERT INTO `locales_source` VALUES (8556,_binary 'Optionally, select or enter filtering, sorting, and page/block display settings; these can be added or changed later.','','none');
INSERT INTO `locales_source` VALUES (8557,_binary 'Click <em>Save and edit</em>. Your view will be created; edit it following the steps in the related topics below.','','none');
