INSERT INTO `locales_source` VALUES (8756,_binary 'Separate extensions with a comma or space. Each extension can contain alphanumeric characters, \'.\', and \'_\', and should start and end with an alphanumeric character.','','none');
INSERT INTO `locales_source` VALUES (8757,_binary 'The list of allowed extensions is not valid. Allowed characters are a-z, 0-9, \'.\', and \'_\'. The first and last characters cannot be \'.\' or \'_\', and these two characters cannot appear next to each other. Separate extensions with a comma or space.','','none');
