INSERT INTO `locales_source` VALUES (8765,_binary 'Under <em>Custom language settings</em>, find the content entity types that should have customized language settings on your site. Check the box next to each one. A section will appear below the list with settings for that entity type.','','none');
INSERT INTO `locales_source` VALUES (8766,_binary 'For each entity type you checked, in the settings section below check the boxes for each entity sub-type that should be <em>Translatable</em> on your site. If the entity type does not have sub-types, there is just one check box for the entity type as a whole.','','none');
