INSERT INTO `locales_source` VALUES (8772,_binary 'There are three types of text that can be translated:','','none');
INSERT INTO `locales_source` VALUES (8773,_binary 'User interface text that is provided by the core software, your install profile, themes, and modules is provided in English, but can be translated into other languages. You can also download translations that community-members have provided.','','none');
