INSERT INTO `locales_source` VALUES (9098,_binary 'For more detailed information, see the <a href=\"https://www.drupal.org/docs/updating-drupal\">Updating Drupal guide</a>. If you are unsure what these terms mean you should probably contact your hosting provider.','','none');
INSERT INTO `locales_source` VALUES (9099,_binary 'Defined on the <a href=\"@appearance\">Appearance Settings</a> page.','','none');
INSERT INTO `locales_source` VALUES (9100,_binary 'Save and go to list','','none');
INSERT INTO `locales_source` VALUES (9101,_binary 'Automatic updating of Drupal core is not supported. See the <a href=\":update-guide\">Updating Drupal guide</a> for information on how to update Drupal core manually.','','none');
INSERT INTO `locales_source` VALUES (9102,_binary 'Other permissions pages','','none');
INSERT INTO `locales_source` VALUES (9103,_binary 'The main Permissions page can be overwhelming, so each module that defines permissions has its own page for setting them. There are links to these pages on the <a href=\":modules\">Extend page</a>. When editing a content type, vocabulary, etc., there is also a Manage permissions tab for permissions related to that configuration.','','none');
INSERT INTO `locales_source` VALUES (9104,_binary 'Account %name has been disabled.','','none');
INSERT INTO `locales_source` VALUES (9105,_binary 'Delete the account and make its content belong to the %anonymous-name user. This action cannot be undone.','','11.4.6');
INSERT INTO `locales_source` VALUES (9106,_binary 'Delete the account and its content. This action cannot be undone.','','none');
INSERT INTO `locales_source` VALUES (9107,_binary 'To log in to this site, your browser must accept cookies from the domain %domain.','','none');
INSERT INTO `locales_source` VALUES (9108,_binary 'Cancellation method','','none');
INSERT INTO `locales_source` VALUES (9109,_binary 'This view will be displayed by visiting this path on your site. You may use \"%\" or named route parameters like \"%node\" in your URL to represent values that will be used for contextual filters: For example, \"node/%node/feed\" or \"view_path/%\". Named route parameters are required when this path matches an existing path. For example, paths such as \"taxonomy/term/%taxonomy_term\" or \"user/%user/custom-view\".','','none');
INSERT INTO `locales_source` VALUES (9110,_binary 'Sort field identifier','','none');
INSERT INTO `locales_source` VALUES (9111,_binary 'This will appear in the URL after the ?, as value of \'sort_by\' parameter, to identify this sort field. Cannot be blank. Only letters, digits and the dot (\'.\'), hyphen (\'-\'), underscore (\'_\'), and tilde (\'~\') characters are allowed.','','none');
INSERT INTO `locales_source` VALUES (9112,_binary 'This identifier is already used by %label sort handler.','','none');
