INSERT INTO `locales_source` VALUES (9590,_binary 'Filters text content in preparation for display.','','none');
INSERT INTO `locales_source` VALUES (9591,_binary 'Lazy load images','','none');
INSERT INTO `locales_source` VALUES (9592,_binary 'Instruct browsers to lazy load images if dimensions are specified. Use in conjunction with and place after the \'Track images uploaded via a Text Editor\' filter that adds image dimensions required for lazy loading. Results can be overridden by <code>&lt;img loading=&quot;eager&quot;&gt;</code>.','','none');
INSERT INTO `locales_source` VALUES (9593,_binary 'Generates help pages and provides a Help block with page-level help.','','none');
INSERT INTO `locales_source` VALUES (9594,_binary 'What are content blocks?','','none');
INSERT INTO `locales_source` VALUES (9595,_binary 'Content blocks are blocks whose content you can edit. You can define one or more <em>block types</em>, and attach fields to each block type. Content blocks can be placed just like blocks provided by other modules.','','none');
INSERT INTO `locales_source` VALUES (9596,_binary 'Overview for managing blocks','','none');
INSERT INTO `locales_source` VALUES (9597,_binary 'The <em>Block</em> module allows you to place blocks in regions of your installed themes, and configure block settings. The <em>Block Content</em> module allows you to manage block types and content blocks. See the related topics listed below for specific tasks.','','none');
INSERT INTO `locales_source` VALUES (9598,_binary 'Creating a content block','','none');
INSERT INTO `locales_source` VALUES (9599,_binary 'Create a content block, which can later be placed on the site.','','none');
INSERT INTO `locales_source` VALUES (9600,_binary 'In the <em>Manage</em> administrative menu, navigate to <em>Content</em>.','','none');
INSERT INTO `locales_source` VALUES (9601,_binary 'Open the @library_link tab.','','none');
INSERT INTO `locales_source` VALUES (9602,_binary 'Click <em>Add content block</em>. If you have more than one block type defined on your site, click the name of the type you want to create.','','none');
