INSERT INTO `locales_target` VALUES (5373,_binary 'Permite que outros usuários entrem em contato com você através de um formulário de contato pessoal que mantém seu endereço de e-mail oculto. Note que alguns usuários privilegiados, como administradores do site, ainda são capazes de contatá-lo mesmo que você opte por desabilitar esta funcionalidade.','pt-br',0);
INSERT INTO `locales_target` VALUES (5374,_binary 'Exemplo: \'webmaster@exemplo.com\' ou \'vendas@exemplo.com,suporte@exemplo.com\'. Para especificar múltiplos destinatários, separe cada endereço de e-mail com uma vírgula.','pt-br',0);
