INSERT INTO `locales_target` VALUES (5721,_binary 'Abas são botões exibidos em uma barra na parte superior da tela. Algumas abas executam uma ação (como iniciar o modo de Edição), enquanto outras abas alternam qual bandeja é aberta.','pt-br',0);
INSERT INTO `locales_target` VALUES (5722,_binary 'Bandejas','pt-br',0);
INSERT INTO `locales_target` VALUES (5723,_binary 'Bandejas são geralmente listas de links que podem ser hierárquicas como um menu. Se uma bandeja for aberta, ela será exibida verticalmente ou horizontalmente abaixo da barra de abas, dependendo da largura do navegador. Somente uma bandeja pode ser aberta por vez. Se você clicar em outra aba, essa bandeja substituirá a bandeja que está sendo exibida. Em navegadores com larguras maiores, o usuário pode alternar de vertical para horizontal usando um link na parte inferior ou direita da bandeja. Menus hierárquicos possuem comportamento de abertura/fechamento apenas no modo vertical; se você exibir uma bandeja contendo um menu hierárquico horizontal, apenas os links do nível superior estarão disponíveis.','pt-br',0);
