INSERT INTO `locales_target` VALUES (5956,_binary 'Buscas procuram por palavras-chave exatas, sem distinção entre maiúsculas e minúsculas. Palavras-chave mais curtas que o comprimento mínimo são ignoradas.','pt-br',0);
INSERT INTO `locales_target` VALUES (5957,_binary 'Use OR em maiúsculas para obter mais resultados. Exemplo: gato OR cachorro (o conteúdo contém \"gato\" ou \"cachorro\").','pt-br',0);
INSERT INTO `locales_target` VALUES (5958,_binary 'Você pode usar AND em maiúsculas para requisitar todas as palavras, mas isso é o mesmo que o comportamento padrão. Exemplo: gato AND cachorro (o mesmo que gato cachorro, o conteúdo deve conter \"gato\" e \"cachorro\").','pt-br',0);
INSERT INTO `locales_target` VALUES (5959,_binary 'Use aspas para buscar uma frase. Exemplo: \"o gato come o rato\".','pt-br',0);
INSERT INTO `locales_target` VALUES (5960,_binary 'É possível preceder palavras-chaves com - para excluí-las; deve-se ainda ter pelo menos uma palavra-chave \"positiva\". Exemplo: gato -cachorro (o conteúdo deve conter gato, mas não deve conter cachorro).','pt-br',0);
