INSERT INTO `locales_target` VALUES (5986,_binary 'O widget <em>Caixas de seleção/botões de opções</em> exibe as entidades existentes para o tipo de entidade como caixas de seleção ou botões de opções com base no <em>Número de valores permitido</em> configurado para o campo.','pt-br',0);
INSERT INTO `locales_target` VALUES (5987,_binary 'O widget <em>Lista de seleção</em> exibe as entidades existentes em uma lista suspensa ou em uma caixa de lista de rolagem com base no <em>Número de valores permitido</em> configurado para o campo.','pt-br',0);
INSERT INTO `locales_target` VALUES (5988,_binary 'O widget <em>Autocompletar automaticamente</em> exibe campos de texto onde os usuários podem digitar etiquetas de entidades com base no <em>Número de valores permitido</em>. O widget pode ser configurado para exibir todas as entidades que contenham os caracteres digitados ou que estejam restritas àquelas que começam com esses caracteres.','pt-br',0);
INSERT INTO `locales_target` VALUES (5989,_binary 'O widget <em>Autocompletar automaticamente (estilo de tags)</em> exibe um campo para diversos textos no qual os usuários podem digitar etiquetas de entidade em uma lista separada por vírgulas.','pt-br',0);
