INSERT INTO `locales_target` VALUES (6003,_binary 'Os campos de texto que permitem formatos de texto são aqueles com a indicação \"formatado\" na descrição. Esses são <em>Texto (formatado, longo, com resumo)</em>, <em>Texto (formatado)</em> e <em>Texto (formatado, longo)</em>. Você não pode alterar o tipo de campo depois que ele for criado.','pt-br',0);
INSERT INTO `locales_target` VALUES (6004,_binary 'Configurando o tipo de link permitido','pt-br',0);
INSERT INTO `locales_target` VALUES (6005,_binary 'Nas configurações do campo é possível definir o tipo de link permitido para <em>somente links internos</em>, <em>somente links externos</em> ou <em>links internos e externos</em>. As opções <em>somente links internos</em> e <em>links internos e externos</em> permitem um widget de autocompletar automaticamente para links internos, de modo que o usuário não precisa copiar ou lembrar uma URL.','pt-br',0);
INSERT INTO `locales_target` VALUES (6006,_binary 'Revisões permitem que você acompanhe diferenças entre múltiplas versões do seu conteúdo e reverta para versões mais antigas.','pt-br',0);
