INSERT INTO `locales_target` VALUES (6205,_binary 'O instalador requer que você crie um diretório de traduções como parte do processo de instalação. Crie o diretório %translations_directory . Mais detalhes sobre a instalação do Drupal  estão disponíveis em <a href=\":install_txt\">INSTALL.txt</a>.','pt-br',0);
INSERT INTO `locales_target` VALUES (6206,_binary 'O instalador requer permissões de leitura para %translations_directory o tempo todo. A seção de documentação de <a href=\":handbook_url\"> problemas de hospedagem web </a> oferece ajuda sobre este e outros tópicos.','pt-br',0);
INSERT INTO `locales_target` VALUES (6207,_binary 'O instalador precisa de permissões de escrita no %translations_directory durante o processo de instalação. O seção <a href=\":handbook_url\">webhosting issues</a> da documentação oferece ajuda sobre este e outros tópicos.','pt-br',0);
INSERT INTO `locales_target` VALUES (6208,_binary 'O instalador precisa contatar o servidor de traduções para baixar um arquivo de tradução. Verifique sua conexão de internet e se o seu site pode acessar o servidor de traduções em <a href=\":server_url\">@server_url</a>.','pt-br',0);
INSERT INTO `locales_target` VALUES (6209,_binary 'O arquivo de tradução para %language não está disponível no servidor de traduções. <a href=\":url\">Escolha outro idioma</a> ou selecione Inglês (English) e traduza o seu site depois.','pt-br',0);
INSERT INTO `locales_target` VALUES (6210,_binary 'O arquivo de tradução para %language não pôde ser baixado. <a href=\":url\">Escolha outro idioma</a> ou selecione Inglês (English) e traduza o seu site depois.','pt-br',0);
INSERT INTO `locales_target` VALUES (6211,_binary 'O instalador @drupal precisa que você crie um %file como parte do processo de instalação. Copie o arquivo %default_file para %file. Mais detalhes sobre a instalação do Drupal estão disponíveis em <a href=\":install_txt\">INSTALL.txt</a>.','pt-br',0);
INSERT INTO `locales_target` VALUES (6212,_binary '@drupal requer permissões de leitura a %file em todas as vezes. A seção <a href=\":handbook_url\">problemas de hospedagem</a> da documentação oferece ajuda neste e em outros tópicos.','pt-br',0);
INSERT INTO `locales_target` VALUES (6213,_binary 'O instalador @drupal precisa de permissões de escrita para %file durante o processo de instalação. A seção <a href=\":handbook_url\">problemas de hospedagem</a> da documentação oferece ajuda neste e em outros tópicos.','pt-br',0);
INSERT INTO `locales_target` VALUES (6214,_binary 'O instalador @drupal falhou ao criar um arquivo %file com o proprietário correto. Acesse seu servidor web, remova o arquivo %file e crie um novo, copiando de %default_file para %file. Mais detalhes sobre a instalação do Drupal estão disponíveis em <a href=\":install_txt\">INSTALL.txt</a>. A seção <a href=\":handbook_url\">problemas de hospedagem</a> da documentação fornece ajuda neste e em outros tópicos.','pt-br',0);
INSERT INTO `locales_target` VALUES (6215,_binary 'Verifique as mensagens e <a href=\":retry\">tente novamente</a>, ou você pode escolher <a href=\":cont\">continuar mesmo assim</a>.','pt-br',0);
