INSERT INTO `locales_target` VALUES (6222,_binary 'A configuração %setting está atualmente configurada para \'%current_value\' mas precisa ser configurada para \'%needed_value\'. Altere-a executando a seguinte consulta: <code>@query</code>','pt-br',0);
