INSERT INTO `locales_target` VALUES (6229,_binary '<ul>\n<li>Para reiniciar, você precisa limpar seu banco de dados e copiar o arquivo <em>default.settings.php</em> sobre o <em>settings.php</em>.</li>\n<li>Para atualizar uma instalação existente, vá para o <a href=\":update-url\">script de atualização</a>.</li>\n<li>Veja seu <a href=\":base-url\">site atual</a>.</li>\n</ul>','pt-br',0);
INSERT INTO `locales_target` VALUES (6230,_binary 'Todas as mudanças necessárias em %dir e %file foram feitas, então você agora deveria remover as permissões de escrita deles para evitar riscos à segurança. Se você não tiver certeza de como fazer isso, consulte o <a href=\":handbook_url\">manual online</a>.','pt-br',0);
