INSERT INTO `locales_target` VALUES (6460,_binary 'Você pode obter mais informações sobre as configurações do agendador de tarefas lendo o <a href=\"@url\">Tutorial do Cron no drupal.org</a>.','pt-br',0);
INSERT INTO `locales_target` VALUES (6461,_binary 'Essa versão não é compatível com Drupal @core_version e deve ser substituída.','pt-br',0);
