INSERT INTO `locales_target` VALUES (6474,_binary 'Módulo responsável pelo vocabulário.','pt-br',0);
INSERT INTO `locales_target` VALUES (6475,_binary 'O módulo Telephone permite que você crie campos que contenham números de telefone. Consulte as páginas <a href=\":field\">ajuda do módulo Field</a> e a <a href=\":field_ui\">ajuda do Field UI</a> para obter informações gerais sobre como criar e gerenciar campos. Para mais informações, consulte a <a href=\":telephone_documentation\">documentação on-line para o módulo Telephone</a>.','pt-br',0);
INSERT INTO `locales_target` VALUES (6476,_binary 'As <em>configurações</em> e a <em>exibição</em> do campo de telefone podem ser configuradas separadamente. Consulte a <a href=\":field_ui\">ajuda do Field UI</a> para mais informações sobre como gerenciar campos e suas exibições.','pt-br',0);
INSERT INTO `locales_target` VALUES (6477,_binary 'O módulo Text permite que você crie campos de texto curtos e longos com resumos opcional. Consulte as páginas <a href=\":field\">ajuda do módulo Field</a> e a <a href=\":field_ui\">ajuda do Field UI</a> para obter informações gerais sobre como criar e gerenciar campos. Para mais informações, consulte a <a href=\":text_documentation\">documentação on-line para o módulo Text</a>.','pt-br',0);
INSERT INTO `locales_target` VALUES (6478,_binary 'As <em>configurações</em> e a <em>exibição</em> do campo de texto podem ser configuradas separadamente. Consulte a <a href=\":field_ui\">ajuda do módulo Field UI</a> para mais informações sobre como gerenciar campos e suas exibições.','pt-br',0);
INSERT INTO `locales_target` VALUES (6479,_binary 'Se escolher <em>Texto (simples)</em> ou <em>Texto (simples, longo)</em>, você restringe a entrada somente para <em>texto simples</em>. Se escolher <em>Texto (formatado)</em>, <em>Texto (formatado, longo)</em> ou <em>Texto (formatado, longo, com resumo)</em>, você permite que os usuários gravem texto formatado. Quais opções estão disponíveis para usuários individuais dependem das configurações na <a href=\":formats\">Página de formatos e editores de texto</a>.','pt-br',0);
INSERT INTO `locales_target` VALUES (6480,_binary 'Número de linhas de resumo: @rows','pt-br',0);
INSERT INTO `locales_target` VALUES (6481,_binary 'O módulo Toolbar fornece uma barra de ferramentas para os administradores do site, que exibe abas e bandejas fornecidas pelo próprio módulo Toolbar e por outros módulos. Para mais informações, consulte a <a href=\":toolbar_docs\">documentação on-line para o módulo Toolbar</a>.','pt-br',0);
