INSERT INTO `locales_target` VALUES (6764,_binary 'O módulo Syslog registra eventos enviando mensagens para o serviço de criação de registros do sistema operacional do seu servidor web. O Syslog é uma ferramenta de administração de registros do sistema operacional que fornece informações valiosas para uso no gerenciamento de sistemas e na auditoria de segurança. Mais adequado para sites de médio e grande porte, o Syslog fornece ferramentas de filtragem que permitem que as mensagens sejam roteadas por tipo e severidade. Para mais informações, consulte a <a href=\":syslog\">documentação on-line para o módulo Syslog</a>, bem como as páginas de documentação do PHP para as funções <a href=\"http://php.net/manual/function.openlog.php\">openlog</a> e <a href=\"http://php.net/manual/function.syslog.php\">syslog</a>.','pt-br',0);
