INSERT INTO `locales_target` VALUES (7921,_binary 'Os tópicos de ajuda de alto nível são listados na página principal <a href=\":help_page\">da Ajuda</a>. Links para outros tópicos, incluindo tópicos de ajuda não-de alto nível, podem ser encontrados no título \"Relacionado\" ao visualizar uma página de tópicos.','pt-br',0);
INSERT INTO `locales_target` VALUES (7922,_binary 'Fornecendo tópicos de ajuda','pt-br',0);
INSERT INTO `locales_target` VALUES (7923,_binary 'Traduzindo tópicos de ajuda','pt-br',0);
INSERT INTO `locales_target` VALUES (7924,_binary 'O título e o texto de corpo dos tópicos de ajuda fornecidos por módulos e temas contribuídos são traduzíveis usando o módulo <a href=\":locale_help\">Interface Translation</a>. Tópicos fornecidos por módulos e temas personalizados também são traduzíveis se tiverem sido vistos pelo menos uma vez em um idioma não-inglês, o que desencadeia colocar seu texto traduzível no banco de dados de tradução.','pt-br',0);
