INSERT INTO `locales_target` VALUES (8500,_binary 'Digite o <em>Link</em>, um dos seguintes:','pt-br',0);
INSERT INTO `locales_target` VALUES (8501,_binary 'Um caminho interno, como <em>/node/add</em>','pt-br',0);
INSERT INTO `locales_target` VALUES (8502,_binary 'Uma URL externa completa','pt-br',0);
