INSERT INTO `locales_target` VALUES (8511,_binary 'Localize o menu que você acabou de adicionar um link e clique em <em>Editar</em> na lista <em>Operações</em>.','pt-br',0);
INSERT INTO `locales_target` VALUES (8512,_binary 'Verifique se a ordem dos links está correta. Se não estiver, arraste os links do menu até que a ordem esteja correta e clique em <em>Salvar</em>.','pt-br',0);
