INSERT INTO `locales_target` VALUES (8516,_binary 'Digite o título do menu, usado como o título padrão do bloco se o menu for exibido como um bloco. Se desejar, também edite o nome de máquina do menu, que é por padrão derivado do título.','pt-br',0);
