INSERT INTO `locales_target` VALUES (8753,_binary 'Elementos semânticos do HTML5 figure e figcaption estão disponíveis para adicionar legendas as imagens.','pt-br',0);
INSERT INTO `locales_target` VALUES (8754,_binary 'Este log não é persistente','pt-br',0);
INSERT INTO `locales_target` VALUES (8755,_binary 'Os registros do módulo de registro de banco de dados podem ser limpos por administradores e tarefas automatizadas de cron, de modo que não devem ser usados para <a href=\":audit_trail_wiki\">registro forense</a>. Para fins forenses, use o módulo Syslog.','pt-br',0);
INSERT INTO `locales_target` VALUES (8756,_binary 'Separe extensões com vírgula ou espaço. Cada extensão pode conter caracteres alfanuméricos, \'.\', e \'_\', e deve começar e terminar com um caractere alfanumérico.','pt-br',0);
INSERT INTO `locales_target` VALUES (8757,_binary 'A lista de extensões permitidas não é válida. Os caracteres permitidos são a-z, 0-9, \'.\', e \'_\'. O primeiro e o último caracteres não podem ser \'.\' ou \'_\', e esses dois caracteres não podem aparecer um ao lado do outro. Separe extensões com vírgula ou espaço.','pt-br',0);
INSERT INTO `locales_target` VALUES (8758,_binary 'Adicione %txt_extension à lista de extensões permitidas para carregar arquivos com segurança com uma extensão de %extension. A extensão %txt_extension será adicionada automaticamente.','pt-br',0);
