INSERT INTO `locales_target` VALUES (8772,_binary 'Existem três tipos de texto que podem ser traduzidos:','pt-br',0);
INSERT INTO `locales_target` VALUES (8773,_binary 'O texto da interface do usuário que é fornecido pelo software principal, seu perfil de instalação, temas e módulos, são fornecidos em Inglês mas podem ser traduzidos para outros idiomas. Você também pode baixar traduções que os membros da comunidade desenvolveram.','pt-br',0);
