INSERT INTO `locales_target` VALUES (8856,_binary 'Atualizar módulos e temas requer <strong>acesso @backends</strong> ao seu servidor. Consulte <a href=\":doc_url\">Estendendo o Drupal</a> para outros métodos de atualização.Atualizar módulos e temas requer acesso ao seu servidor através de um dos seguintes métodos: <strong>@backends</strong>. Consulte <a href=\":doc_url\">Estendendo o Drupal</a> para outros métodos de atualização.','pt-br',0);
