INSERT INTO `locales_target` VALUES (9103,_binary 'A página principal de Permissões pode ser muito pesada, de modo que cada módulo que define permissões tem sua própria página para defini-las. Existem links para essas páginas na página <a href=\":modules\">Estender</a>. Ao editar um tipo de conteúdo, vocabulário, etc., há também uma aba Gerenciar permissões para permissões relacionadas a essa configuração.','pt-br',0);
