INSERT INTO `locales_target` VALUES (9109,_binary 'Esta view será exibida visitando este caminho em seu site. Você pode usar \"%\" ou parâmetros de rota como \"%node\" em sua URL para representar valores que serão usados para filtros contextuais. Por exemplo, \"node/%node/feed\" ou \"view_path/%\". Parâmetros de rota nomeados são necessários quando este caminho corresponde a um caminho existente. Por exemplo, caminhos como “taxonomy/term/%taxonomy_term\" ou “user/%user/custom-view\".','pt-br',0);
INSERT INTO `locales_target` VALUES (9110,_binary 'Identificador do campo de ordenamento','pt-br',0);
INSERT INTO `locales_target` VALUES (9111,_binary 'Isso aparecerá na URL após o ? como valor do parâmetro \'sort_by\', para identificar esse campo de classificação. Não pode ficar em branco. São permitidas apenas letras, dígitos e os caracteres ponto (\'.\'), hífen (\'-\'), sublinhado (\'_\') e til (\'~\').','pt-br',0);
