INSERT INTO `locales_target` VALUES (9137,_binary 'Estes são os títulos que aparecerão nos títulos suspensos. Se um título não for escolhido aqui, isso não significa necessariamente que a tag correspondente seja proibida no formato de texto.','pt-br',0);
