INSERT INTO `locales_target` VALUES (9228,_binary 'A principal maneira de alterar a aparência geral do seu site é alternar o tema padrão. Os módulos principais Layout Builder e Layout Discovery permitem que você defina layouts para o conteúdo do seu site, e o módulo principal Breakpoint ajuda os temas para alterar a aparência em dispositivos de tamanhos diferentes. Consulte os tópicos relacionados listados abaixo para tarefas específicas.','pt-br',0);
