INSERT INTO `locales_target` VALUES (9231,_binary 'O módulo principal Settings Tray fornece capacidade de editar rapidamente as configurações em linha. Ele requer o módulo principal Contextual Links para expor os links que permitem editar no local.','pt-br',0);
