INSERT INTO `locales_target` VALUES (9233,_binary 'Para seguir estas etapas para editar as configurações no local, o módulo principal Settings Tray deve estar instalado. Além disso, o módulo principal Toolbar ou um módulo substituto da comunidade deve ser instalado. Você precisa ter a permissão <em>Usar links contextuais</em>, bem como a permissão para editar o conteúdo ou as configurações específicas.','pt-br',0);
