INSERT INTO `locales_target` VALUES (9236,_binary 'Expõe entidades e outros recursos para outros aplicativos usando uma implementação <a href=\"https://en.wikipedia.org/wiki/Representational_state_transfer\">REST</a> . Os dados são trocados usando um formato de serialização, como JSON, e transferidos usando um método de autenticação, como a Autenticação Básica HTTP.','pt-br',0);
