INSERT INTO `locales_target` VALUES (9268,_binary 'Você pode optar por enviar email somente se uma atualização de segurança estiver disponível ou ser notificado sobre todas as versões mais recentes. Se houver atualizações disponíveis do core do Drupal ou de qualquer um dos módulos e temas instalados, seu site sempre mostrará uma mensagem na página do <a href=\":status_report\">relatório de status</a>. Se houver uma atualização de segurança, uma mensagem de erro será apresentada nas páginas de administração para usuários com <a href=\":update_permissions\">permissão para exibir notificações de atualização</a>.','pt-br',0);
