INSERT INTO `locales_target` VALUES (9279,_binary 'Se o botão <em>Fonte</em> estiver disponível na barra de ferramentas, os usuários podem clicar neste botão para desativar o editor visual e editar o código HTML diretamente. Depois de voltar, o editor visual usa as tags HTML permitidas via configuração de plugin (e não explicitamente proibidas por filtros) para formatar o texto. As tags não habilitadas através da configuração do plugin serão retiradas do código HTML quando o usuário voltar para o editor de texto.','pt-br',0);
