INSERT INTO `locales_target` VALUES (9358,_binary 'O código da aplicação Drupal deve ter permissão de escrita para usar atualizações automáticas. Isso inclui o core do Drupal, módulos, temas e as dependências do Composer no diretório <code>vendor</code>. Isso torna as atualizações automáticas incompatíveis com algumas plataformas de hospedagem.','pt-br',0);
INSERT INTO `locales_target` VALUES (9359,_binary 'Como o Package Manager modifica a base de código do site atual, ele é intencionalmente limitado de certas formas para evitar alterações inesperadas no site ativo:','pt-br',0);
