INSERT INTO `locales_target` VALUES (9384,_binary 'Um comunicado de segurança é um anúncio público sobre um problema de segurança relatado no software principal. Os projetos contribuídos com um ícone de escudo e \"Versões estáveis para este projeto são cobertas pela política de consultoria de segurança\" na página do projeto também são cobertos pela política de consultoria de segurança do Drupal. Os avisos de segurança são gerenciados pela <a href=\"https://www.drupal.org/drupal-security-team\">Equipe de Segurança do Drupal</a>.','pt-br',0);
