INSERT INTO `locales_target` VALUES (9592,_binary 'Instrua os navegadores a carregar imagens lentamente se as dimensões forem especificadas. Usar em conjunto com \'Rastrear imagens carregadas por meio de um editor de texto\' e colocar após o filtro que adiciona as dimensões de imagem necessárias para o carregamento lento. Os resultados podem ser substituídos por <code>&lt;img loading=&quot;eager&quot;&gt;</code>.','pt-br',0);
INSERT INTO `locales_target` VALUES (9593,_binary 'Gera páginas de ajuda e fornece um bloco de Ajuda com ajuda no nível da página.','pt-br',0);
INSERT INTO `locales_target` VALUES (9594,_binary 'O que são blocos de conteúdo?','pt-br',0);
INSERT INTO `locales_target` VALUES (9595,_binary 'Os blocos de conteúdo são blocos cujo conteúdo você pode editar. Você pode definir um ou mais <em>tipos de bloco</em> e anexar campos a cada tipo de bloco. Os blocos de conteúdo podem ser colocados da mesma forma que os blocos fornecidos por outros módulos.','pt-br',0);
INSERT INTO `locales_target` VALUES (9596,_binary 'Visão geral para gerenciamento de blocos','pt-br',0);
INSERT INTO `locales_target` VALUES (9597,_binary 'O módulo <em>Block</em> permite que você coloque blocos em regiões de seus temas instalados e defina as configurações de bloco. O módulo <em>Block Content</em> permite gerenciar tipos de blocos e blocos de conteúdo. Consulte os tópicos relacionados listados abaixo para tarefas específicas.','pt-br',0);
INSERT INTO `locales_target` VALUES (9598,_binary 'Criando um bloco de conteúdo','pt-br',0);
INSERT INTO `locales_target` VALUES (9599,_binary 'Crie um bloco de conteúdo que pode ser colocado posteriormente no site.','pt-br',0);
INSERT INTO `locales_target` VALUES (9600,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Conteúdo</em>.','pt-br',0);
INSERT INTO `locales_target` VALUES (9601,_binary 'Abra a guia @library_link.','pt-br',0);
INSERT INTO `locales_target` VALUES (9602,_binary 'Clique em <em>Adicionar bloco de conteúdo</em>. Se você tiver mais de um tipo de bloco definido em seu site, clique no nome do tipo que deseja criar.','pt-br',0);
INSERT INTO `locales_target` VALUES (9603,_binary 'Definindo um tipo de bloco','pt-br',0);
INSERT INTO `locales_target` VALUES (9604,_binary 'Defina um tipo de bloco e seus campos.','pt-br',0);
INSERT INTO `locales_target` VALUES (9605,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Estrutura</em> &gt; <em>@types_link</em>.','pt-br',0);
INSERT INTO `locales_target` VALUES (9606,_binary 'Clique em  <em>Adicionar tipo de bloco</em>.','pt-br',0);
INSERT INTO `locales_target` VALUES (9607,_binary 'Um comentário é um conteúdo normalmente postado por um visitante do site que fornece discussão ou comentário sobre outro conteúdo, como postagens de blog e artigos de notícias. Os comentários são um tipo de entidade de conteúdo e podem ter campos que armazenam texto, marcação HTML e outros dados. Os comentários são anexados a outras entidades de conteúdo por meio de campos de comentário. Consulte @content_structure_topic para obter mais informações sobre entidades e campos de conteúdo.','pt-br',0);
INSERT INTO `locales_target` VALUES (9608,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>Região e Idioma</em> &gt; <em>@config_translation_link</em>.','pt-br',0);
INSERT INTO `locales_target` VALUES (9609,_binary 'Os formulários de contato pessoais e de todo o site sempre terão os campos <em>Assunto</em> e <em>Mensagem</em>. Você pode adicionar novos campos para os usuários preencherem, se desejar. Observe que, se você quiser exibir outro conteúdo em uma página de formulário, como texto ou imagens, poderá usar um bloco de conteúdo.','pt-br',0);
INSERT INTO `locales_target` VALUES (9610,_binary 'Os usuários com <em>permissões de moderação de conteúdo</em> podem alterar os estados do fluxo de trabalho. Há permissões separadas para cada transição. Consulte Permissões &gt; <em>@content_moderation_permissions_link</em> para configurar permissões de moderação de conteúdo.','pt-br',0);
INSERT INTO `locales_target` VALUES (9611,_binary 'Localize a entidade que você deseja moderar na página de exibição de moderação de conteúdo, se você criou uma, ou na página administrativa apropriada para gerenciar esse tipo de entidade (como a página de administração de itens de conteúdo; consulte @content_link).','pt-br',0);
INSERT INTO `locales_target` VALUES (9612,_binary 'Para implementar seu plano, no menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>Fluxo de Trabalho</em> &gt; <em>@workflows_link</em>. Uma lista de fluxos de trabalho é mostrada, incluindo o fluxo de trabalho padrão <em>Editorial</em> que você pode adaptar.','pt-br',0);
INSERT INTO `locales_target` VALUES (9613,_binary 'Em <em>Este fluxo de trabalho se aplica a:</em>, localize o tipo de entidade ao qual você deseja que esse fluxo de trabalho se aplique, como Revisões de conteúdo, Revisões de bloco de conteúdo ou Revisões de termos de taxonomia. Clique em <em>Selecionar</em>.','pt-br',0);
INSERT INTO `locales_target` VALUES (9614,_binary 'Siga as etapas de @user_permissions_topic para atribuir permissões para cada transição em papéis. As permissões estão listadas na seção <em>@content_moderation_permissions_link</em>. Há uma permissão para cada transição em cada fluxo de trabalho.','pt-br',0);
INSERT INTO `locales_target` VALUES (9615,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>Região e Idioma</em> &gt; <em>@translation_settings_link</em>.','pt-br',0);
INSERT INTO `locales_target` VALUES (9616,_binary 'Uma <em>entidade de conteúdo</em> (ou, mais comumente, <em>entidade</em>) é um item de dados de conteúdo, que pode consistir em texto, marcação HTML, imagens, arquivos anexados e outros dados. As entidades de conteúdo são agrupadas em <em>tipos de entidade</em>, que têm finalidades diferentes e são exibidas de maneiras muito diferentes no site. A maioria dos tipos de entidade também é dividida em <em>subtipos de entidade</em>, que são divisões dentro de um tipo de entidade para permitir variações menores na forma como as entidades são usadas e exibidas. Por exemplo, o tipo de entidade <em>de item de conteúdo</em> que armazena conteúdo no nível da página é dividido em subtipos de <em>tipo de conteúdo</em>; o tipo <em>de entidade de bloco de conteúdo</em> tem <em>tipos de bloco</em>; mas o tipo <em>de entidade Usuário</em> (para informações de perfil de usuário) não tem subtipos.','pt-br',0);
INSERT INTO `locales_target` VALUES (9617,_binary 'Dependendo dos módulos do núcleo e de contribuição que você instalou em seu site, os tópicos relacionados abaixo e outros tópicos listados na página de ajuda principal (consulte @help_link) ajudarão você com tarefas relacionadas à estrutura de conteúdo.','pt-br',0);
INSERT INTO `locales_target` VALUES (9618,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>Região e Idioma</em> &gt; @languages_link.','pt-br',0);
INSERT INTO `locales_target` VALUES (9619,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>Região e Idioma</em> &gt; <em>Idiomas</em> &gt; @detection_link.','pt-br',0);
INSERT INTO `locales_target` VALUES (9620,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>Região e Idioma</em> &gt; <em>Tradução da interface do usuário</em> &gt; @import_link.','pt-br',0);
INSERT INTO `locales_target` VALUES (9621,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>Região e Idioma</em> &gt; @translate_link.','pt-br',0);
INSERT INTO `locales_target` VALUES (9622,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>Região e Idioma</em> &gt; @language_link.','pt-br',0);
INSERT INTO `locales_target` VALUES (9623,_binary 'Quando os usuários visitam a página de pesquisa principal (consulte @search_link), eles verão as páginas de pesquisa configuradas às quais têm acesso. Cada página de pesquisa tem um formulário de pesquisa e a página exibirá os resultados da pesquisa depois que o usuário inserir palavras-chave no formulário e clicar no botão de pesquisa.','pt-br',0);
INSERT INTO `locales_target` VALUES (9624,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>&gt; Desenvolvimento</em> <em>@performance_link</em>.','pt-br',0);
