INSERT INTO `locales_target` VALUES (9627,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>Região e Idioma</em> &gt; <em>@datetime_link</em>.','pt-br',0);
INSERT INTO `locales_target` VALUES (9628,_binary 'Na seção <em>Páginas de erro</em>, digite a URL das páginas 403/404, começando após a URL da página inicial do site. Por exemplo, se a URL do seu site é <em>https://example.com</em> e sua página 404 é <em>https://example.com/not-found</em>, você deve digitar <em>/not-found</em>.','pt-br',0);
