INSERT INTO `locales_target` VALUES (9630,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Configuração</em> &gt; <em>Desenvolvimento</em> &gt; <em>@maintenance_link</em>.','pt-br',0);
