INSERT INTO `locales_target` VALUES (9633,_binary 'No menu administrativo <em>Gerenciar</em>, navegue até <em>Relatórios</em> &gt; <em>@status_link</em> para ver um relatório que resume a integridade e o status do seu site. Se houver algum aviso ou erro, você precisará corrigi-lo. Atente-se a todas próximas versões de segurança altamente críticas que podem afetar seu site.','pt-br',0);
