INSERT INTO `locales_target` VALUES (9635,_binary 'Clique no link <em>Desinstalar</em> para desinstalar o tema. Se não houver um link <em>Desinstalar</em>, o tema não poderá ser desinstalado porque está sendo usado como o tema padrão do site, usado como o <em>tema Administração</em> ou é o tema base para outro tema instalado.','pt-br',0);
INSERT INTO `locales_target` VALUES (9636,_binary 'Os campos de referência de taxonomia podem ser adicionados a qualquer entidade, como contas de usuário, blocos de conteúdo ou itens de conteúdo regulares. Se você usá-los para classificar itens de conteúdo regulares, seu site será configurado automaticamente com páginas de listagem de taxonomia para cada termo. Cada uma dessas páginas lista todos os itens de conteúdo classificados com esse termo.','pt-br',0);
