INSERT INTO `locales_target` VALUES (9641,_binary 'Views que usam um formato de exibição de tabela podem incluir um formulário de operações em massa, que permite que os usuários com permissão suficiente selecionem um ou mais itens da view e apliquem uma ação administrativa a eles. As ações em massa disponíveis são específicas para o tipo de dados base da view; por exemplo, uma view de itens de conteúdo pode dar suporte a ações de publicação e cancelamento de publicação em massa. Se você tiver o módulo Actions UI do núcleo instalado, consulte o tópico relacionado \"Configurando ações\" para obter mais informações sobre ações.','pt-br',0);
INSERT INTO `locales_target` VALUES (9642,_binary 'Se você ainda não estiver editando sua exibição, no menu administrativo <em>Gerenciar</em>, navegue até <em>Estrutura</em> <em>&gt; @views_link</em>. Localize a vista que você deseja editar e clique no link <em>Editar</em>.','pt-br',0);
INSERT INTO `locales_target` VALUES (9643,_binary 'Adicione uma ou mais ações existentes como operações em massa em uma view de estilo de tabela existente. Se você tiver o módulo Actions UI do núcleo instalado, consulte o tópico relacionado \"Configurando ações\" para obter mais informações sobre ações.','pt-br',0);
