INSERT INTO `locales_target` VALUES (9988,_binary '%current_display: The link in the %area area points to the %linked_display display which uses different settings than the %current_display display for: %unequal_options. To make sure users see the exact same result when clicking the link, check that the settings are the same.','pt-br',0);
INSERT INTO `locales_target` VALUES (9989,_binary 'Espaços reservados numéricos não podem ser usados. Use espaços reservados simples (%).','pt-br',0);
INSERT INTO `locales_target` VALUES (9990,_binary 'Se marcado, vários valores para este campo serão mostrados na mesma linha. Se não estiver marcado, cada valor neste campo criará uma nova linha. Se estiver usando agrupar por, certifique-se de agrupar por \"ID da entidade\" para que essa configuração tenha algum efeito.','pt-br',0);
INSERT INTO `locales_target` VALUES (9991,_binary 'Isso aparecerá na URL após o ? para identificar esse filtro. Não pode ficar em branco. Somente letras, dígitos e os caracteres de ponto (\".\"), hífen (\"-\"), sublinhado (\"_\") e til (\"~\") são permitidos. @reserved_identifiers são palavras reservadas e não podem ser usadas.','pt-br',0);
