INSERT INTO `locales_target` VALUES (10036,_binary 'A data atual em um formato personalizado. Consulte <a href=\"https://www.php.net/manual/datetime.format.php#refsect1-datetime.format-parameters\">a documentação do PHP</a> para obter detalhes.','pt-br',0);
