INSERT INTO `locales_target` VALUES (10059,_binary 'Se o módulo Interface Translation estiver instalado, esta página fornecerá uma visão geral de quanto da interface do site foi traduzida para cada idioma configurado.','pt-br',0);
INSERT INTO `locales_target` VALUES (10060,_binary 'Dependendo dos recursos do seu site, os módulos adicionais que você pode querer instalar são:','pt-br',0);
