INSERT INTO `locales_target` VALUES (10291,_binary 'O módulo Workflows fornece uma API e uma interface para criar fluxos de trabalho com transições entre diferentes estados (por exemplo, publicação ou status do usuário). Eles precisam ser fornecidos por outros módulos, como o módulo <a href=\":moderation\">Content Moderation</a>. Para obter mais informações, consulte a <a href=\":workflow\">documentação on-line do módulo Workflows</a>.','pt-br',0);
INSERT INTO `locales_target` VALUES (10292,_binary 'O módulo Workflows fornece uma API e uma interface para criar fluxos de trabalho com transições entre diferentes estados (por exemplo, publicação ou status do usuário). Eles precisam ser fornecidos por outros módulos, como o módulo Content Moderation. Para obter mais informações, consulte a <a href=\":workflow\">documentação on-line do módulo Workflows</a>.','pt-br',0);
