INSERT INTO `locales_target` VALUES (10295,_binary 'Você <em>só</em> pode adicionar fluxos de trabalho na <a href=\":workflows\">página Fluxos de trabalho</a> depois de instalar um módulo que aproveite a API, como o módulo Moderação de conteúdo.','pt-br',0);
