INSERT INTO `locales_target` VALUES (10299,_binary 'Uma transição define em qual estado um item pode ser salvo como próximo. Ele tem um estado de destino, mas pode ter vários estados <em>de</em> nos quais a transição pode ser aplicada. Transições podem ser adicionadas quando você adiciona ou edita um fluxo de trabalho na página <a href=\":workflows\">Fluxos de trabalho</a>.','pt-br',0);
